entries[9294] = { ["name"] = "Rezept: Wildrankentrank", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Wildrankentranks.\nBenötigt Klassische Alchemie\n(225)\nVerkaufspreis:\nWildrankentrank\nBenutzen: Stellt 462 Gesundheit und 462 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Wildranke , Lila Lotus , Kristallphiole" }
