entries[9296] = { ["name"] = "Rezept: Arthas' Gabe", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Arthas' Gabe.\nBenötigt Klassische Alchemie\n(240)\nVerkaufspreis:\nArthas' Gabe\nBenutzen: Gewährt eine Chance von 30%, Nahkampfangreifer mit einem Fluch zu belegen, der ihren erlittenen Schaden 3 Min. lang um 0 erhöht. Hält 30 Min. lang an. Wächterelixier. (Procchance: 30%) (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Blindkraut (3), Kristallphiole" }
entries[9297] = { ["name"] = "Rezept: Elixier der Traumvision", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Elixiers der Traumvision.\nBenötigt Klassische Alchemie\n(240)\nVerkaufspreis:\nElixier der Traumvision\nBenutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Lila Lotus (3), Kristallphiole" }
