entries[9303] = { ["name"] = "Rezept: Stein der Weisen", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Steins der Weisen.\nBenötigt Klassische Alchemie\n(50)\nVerkaufspreis:\nStein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2 Stärke\n+2 Beweglichkeit\n+2 Intelligenz\n+2 Ausdauer\n+ 2 Vielseitigkeit\nBenötigt Klassische Alchemie\n(50)\n\"Erforderlich für alchemistische Transmutation.\"\nVerkaufspreis:\nBenötigt Eisenbarren (4), Schwarzes Vitriol , Lila Lotus (4), Feuerblüte (4)\nOptionale Reagenzien: [] (#47)" }
